  ('f70072a9-2c15-4dfd-ae6f-a5c63bc65948', 'c9d0e1f2-3a4b-4d03-8a23-3e4f5a6b7c33', 'debd5c29-c040-4566-9df4-27db5b722461', 'concept'::public.curated_course_node_type, 'Tradeoffs among performance, cost, beauty, and justice', null, 2),
