  ('99d3485a-b8ed-4102-9d74-562dff6ab835', 'c9d0e1f2-3a4b-4d03-8a23-3e4f5a6b7c33', 'abb001d7-061d-46c0-baf8-e1245310657c', 'concept'::public.curated_course_node_type, 'Temperature, humidity, solar radiation, wind, and precipitation', null, 0),
