  ('133a057b-8344-4e63-9f97-afea30802da6', 'c9d0e1f2-3a4b-4d03-8a23-3e4f5a6b7c33', '414598db-42cd-4812-97b8-948f5cda0d7d', 'concept'::public.curated_course_node_type, 'Climate-specific design priorities', null, 2),
