  ('8410defb-da8e-41b6-bce4-6498c60af836', 'c9d0e1f2-3a4b-4d03-8a23-3e4f5a6b7c33', '54fd51ab-5968-4f52-a8d8-4648222b8d1b', 'concept'::public.curated_course_node_type, 'Load reduction before generation', null, 0),
