update public.learning_paths
set
  title = 'Sustainable Design',
  goal = 'Sustainable Design',
  summary = 'Sustainable Design is an advanced architecture course on climate-responsive, low-carbon, healthy, resilient, and equitable building design. Students learn to translate sustainability values into measurable design goals, technical strategies, life-cycle decisions, and post-occupancy evidence. The course connects studio judgment with building science, environmental systems, materials, site ecology, certification frameworks, and climate adaptation.',
  data = $susdjson${"slug": "sustainable-design", "title": "Sustainable Design", "description": "Sustainable Design is an advanced architecture course on climate-responsive, low-carbon, healthy, resilient, and equitable building design. Students learn to translate sustainability values into measurable design goals, technical strategies, life-cycle decisions, and post-occupancy evidence. The course connects studio judgment with building science, environmental systems, materials, site ecology, certification frameworks, and climate adaptation.", "topics": [{"id": "c1d2622b-a1ca-42ff-a152-da1bdea24ba6", "type": "topic", "title": "Sustainability Principles and Design Ethics", "description": "This opening topic frames sustainable design as an ethical, technical, ecological, and cultural practice. Students learn to define sustainability in ways that can guide real design decisions rather than remain a vague aspiration.", "children": [{"id": "1203d54f-6732-4bae-b7dc-24845097ed66", "type": "subtopic", "title": "Sustainability frameworks", "children": [{"id": "458f9abc-e369-40c4-a615-6a878c5ea7db", "type": "concept", "title": "Triple bottom line and regenerative design"}, {"id": "95733fd7-251f-44d5-811d-f9cfa9476a0d", "type": "concept", "title": "United Nations Sustainable Development Goals"}, {"id": "df6eeae6-0811-49ed-912f-e482e650cda9", "type": "concept", "title": "AIA Framework for Design Excellence and whole-building thinking"}], "description": "Students compare the major ideas used to structure sustainable design goals and responsibilities."}, {"id": "8059a5f1-699e-4b01-99f7-5dc1e3c611df", "type": "subtopic", "title": "Design ethics and responsibility", "children": [{"id": "df8334e5-3c91-42d8-b492-6416f991306c", "type": "concept", "title": "Duty of care and professional judgment"}, {"id": "8aa5e85a-7e37-482d-a0f0-cbd833d65a3c", "type": "concept", "title": "Intergenerational equity"}, {"id": "2bd5214b-9615-436f-9c83-f628e38d4af9", "type": "concept", "title": "Avoiding greenwashing and shallow claims"}], "description": "This subtopic asks who benefits, who bears risk, and what obligations designers have to communities and future users."}, {"id": "debd5c29-c040-4566-9df4-27db5b722461", "type": "subtopic", "title": "Systems thinking", "children": [{"id": "282074e5-325a-460f-ab98-2be5c79bbf84", "type": "concept", "title": "Feedback loops and unintended consequences"}, {"id": "5c77e602-2d32-424f-b6f4-af692bacddb2", "type": "concept", "title": "Boundaries and scales of analysis"}, {"id": "f70072a9-2c15-4dfd-ae6f-a5c63bc65948", "type": "concept", "title": "Tradeoffs among performance, cost, beauty, and justice"}], "description": "Students learn to see buildings as parts of larger energy, water, material, ecological, social, and economic systems."}]}, {"id": "86303cfa-7b9d-4781-b05b-9efe3a3b8b00", "type": "topic", "title": "Climate-Responsive Site and Bioclimatic Analysis", "description": "Sustainable design starts with climate and place. Students learn to read sun, wind, temperature, humidity, topography, ecology, and urban context before committing to form or systems.", "children": [{"id": "abb001d7-061d-46c0-baf8-e1245310657c", "type": "subtopic", "title": "Climate data and microclimate", "children": [{"id": "99d3485a-b8ed-4102-9d74-562dff6ab835", "type": "concept", "title": "Temperature, humidity, solar radiation, wind, and precipitation"}, {"id": "6e498951-a869-401a-9134-911d374a32a1", "type": "concept", "title": "Urban heat island effects"}, {"id": "78009b5e-c3de-4a7c-a5b5-c7db4c54b54e", "type": "concept", "title": "Weather files, psychrometric charts, and climate summaries"}], "description": "Students interpret climate files and local conditions as design inputs."}, {"id": "3fc989fd-9f9c-4b98-879e-e46ff4098504", "type": "subtopic", "title": "Site ecology and orientation", "children": [{"id": "48e6fe0d-364c-4cc4-a694-402ac295a5ff", "type": "concept", "title": "Solar orientation and shading context"}, {"id": "4869d0c9-22ac-4002-8a6c-113469ea8949", "type": "concept", "title": "Topography, soils, vegetation, and drainage"}, {"id": "ab20a946-adfc-4723-a3dd-fb6b12f95a03", "type": "concept", "title": "Habitat protection and landscape continuity"}], "description": "The goal is to place buildings in ways that work with existing land, water, habitat, and solar access."}, {"id": "414598db-42cd-4812-97b8-948f5cda0d7d", "type": "subtopic", "title": "Bioclimatic design strategies", "children": [{"id": "484a9715-e6c7-456f-9b23-5a3ab7239a43", "type": "concept", "title": "Heating-dominated, cooling-dominated, mixed, and humid climates"}, {"id": "5aa98d89-0eb6-4aa3-bdf7-83ef7a62c59b", "type": "concept", "title": "Comfort targets by season"}, {"id": "133a057b-8344-4e63-9f97-afea30802da6", "type": "concept", "title": "Climate-specific design priorities"}], "description": "Students connect climate analysis to passive and active design choices."}]}, {"id": "1030814e-2a7c-41ec-81f8-4ac7fc7c26cc", "type": "topic", "title": "Passive Design Strategies", "description": "Passive design reduces loads before adding equipment. Students learn how form, massing, orientation, shading, ventilation, insulation, and thermal mass can improve comfort with less energy.", "children": [{"id": "cbe9acae-57e1-443a-8a64-c77d6d749dd9", "type": "subtopic", "title": "Passive heating and cooling", "children": [{"id": "756e1f83-843b-4fdd-be0b-00ef9aa6b626", "type": "concept", "title": "Direct gain, indirect gain, and thermal mass"}, {"id": "4f6e0a73-829e-4dd9-9603-200b9d979be0", "type": "concept", "title": "Night flushing and stack ventilation"}, {"id": "90e90db0-9811-4010-af4b-21ec8e5630e3", "type": "concept", "title": "Shading, insulation, and airtightness"}], "description": "Students learn to control heat gain, heat loss, and thermal storage through architectural decisions."}, {"id": "68e9815e-c75b-45c9-a295-473341466704", "type": "subtopic", "title": "Natural ventilation", "children": [{"id": "28011d51-c86d-49df-aa20-9634339d50eb", "type": "concept", "title": "Cross ventilation and pressure zones"}, {"id": "25d23986-53cc-460c-9798-ce8af4e6b35e", "type": "concept", "title": "Stack effect and atria"}, {"id": "b674fa45-ab2f-4fa2-82a2-a33326271f15", "type": "concept", "title": "Air quality, acoustics, security, and climate limits"}], "description": "This subtopic teaches airflow as a design resource, not only a mechanical-system problem."}, {"id": "36a51c66-1ab8-49d3-aed5-f73a65fd6713", "type": "subtopic", "title": "Load reduction through form", "children": [{"id": "2eb6ec36-df22-4183-a686-1df27f528770", "type": "concept", "title": "Surface-area-to-volume ratio"}, {"id": "7bd998ea-17d9-426a-bacc-bd5b37315de2", "type": "concept", "title": "Window-to-wall ratio"}, {"id": "c3dea84d-7b17-4aa1-8325-3a3b8396e7cb", "type": "concept", "title": "Compactness, depth, and program zoning"}], "description": "Students learn how massing and envelope choices reduce demand before systems are selected."}]}, {"id": "6d9fe364-a7a6-4f8c-85ad-7a060cd0bffa", "type": "topic", "title": "Building Envelope, Facades, and Thermal Performance", "description": "The envelope mediates between climate and comfort. Students learn to design wall, roof, window, and facade assemblies that manage heat, air, vapor, moisture, daylight, durability, and constructability.", "children": [{"id": "6b46f36d-cfe7-4eac-a74c-2cc17145820b", "type": "subtopic", "title": "Thermal control layers", "children": [{"id": "b59260ac-21c5-43bf-9ce9-178099bf6bda", "type": "concept", "title": "Insulation, air barriers, vapor control, and water control"}, {"id": "9ab784f6-9083-47d2-a907-cf3ee1ac6a3e", "type": "concept", "title": "Thermal bridges and continuity"}, {"id": "eb95b9e9-7352-4c88-bf5a-464de7e3e4ea", "type": "concept", "title": "U-values, R-values, SHGC, and airtightness"}], "description": "Students identify the control layers that make high-performance buildings durable and efficient."}, {"id": "7f0b6cc5-67f1-44d2-a62d-3fdc44bbf918", "type": "subtopic", "title": "Facade design and detailing", "children": [{"id": "916c1e09-a23a-473c-9cd6-cbe42af7624e", "type": "concept", "title": "Opaque and glazed facade systems"}, {"id": "2e8aa286-a143-4059-be49-0a5eed157956", "type": "concept", "title": "Shading devices and dynamic facades"}, {"id": "2d6fc0b5-682c-4ebf-b3aa-03873adf5570", "type": "concept", "title": "Durability, access, cleaning, and replacement"}], "description": "This subtopic connects visual expression to performance, assembly logic, and maintenance."}, {"id": "b0daa018-6468-441a-aeff-b768a86df3cc", "type": "subtopic", "title": "Moisture and enclosure risk", "children": [{"id": "255f233d-bf44-4397-be22-3a2a9b2220b7", "type": "concept", "title": "Dew point and condensation risk"}, {"id": "ae8e2a78-99d6-455c-8925-5beecbcb2457", "type": "concept", "title": "Rain screens and drainage planes"}, {"id": "a2927e3d-0967-45e5-8025-ff500ad01705", "type": "concept", "title": "Hygrothermal analysis and commissioning"}], "description": "Students learn why high-performance envelopes fail when condensation, rain control, and drying potential are ignored."}]}, {"id": "e0a13925-e60e-4b02-af9b-df4c8343896a", "type": "topic", "title": "Daylighting, Visual Comfort, and Solar Control", "description": "Daylighting improves energy performance and human experience when it is controlled carefully. Students learn to balance daylight access, glare, heat gain, views, privacy, and program needs.", "children": [{"id": "cceeb610-d978-4115-8a7f-a3a348c6be70", "type": "subtopic", "title": "Daylight availability and distribution", "children": [{"id": "cf4af202-340a-4c40-ac0a-5e3f5a27371a", "type": "concept", "title": "Daylight factor and daylight autonomy"}, {"id": "e6ae5894-e3c4-4b96-978a-f3fc7cf55a57", "type": "concept", "title": "Room depth, window head height, and ceiling reflectance"}, {"id": "b355b7eb-c3ce-4022-9ebc-a312cc4c6695", "type": "concept", "title": "Light shelves, clerestories, and atria"}], "description": "Students learn how geometry, glazing, reflectance, and sky conditions shape daylight in rooms."}, {"id": "3a6044f7-6c45-4106-9ef6-9d66a2972fdf", "type": "subtopic", "title": "Glare and visual comfort", "children": [{"id": "c09e3d18-7907-49b3-8d30-f087ef2fb420", "type": "concept", "title": "Direct sun and contrast control"}, {"id": "9772113e-c831-4891-bd98-b3716c80fda4", "type": "concept", "title": "Useful daylight illuminance"}, {"id": "4c859524-9d51-4b24-9ff3-37e406736c75", "type": "concept", "title": "Shading, blinds, fritting, and interior layout"}], "description": "This subtopic teaches students to evaluate whether daylight is usable rather than merely abundant."}, {"id": "ed6ac775-2707-4219-a0ce-c526a02f9732", "type": "subtopic", "title": "Solar control integration", "children": [{"id": "c9350317-abe9-4027-92c1-77d9ab87835a", "type": "concept", "title": "Orientation-specific shading"}, {"id": "22715be1-013c-4075-a744-a2e6934c7f53", "type": "concept", "title": "Overhangs, fins, screens, and vegetation"}, {"id": "d987b809-38bd-4c14-b49a-f2d8a5aeb8a2", "type": "concept", "title": "Solar heat gain and cooling loads"}], "description": "Students connect daylighting to thermal performance and facade expression."}]}, {"id": "be2e57f1-d88b-4d8b-8fac-6ae9423114b5", "type": "topic", "title": "Energy Efficiency and High-Performance Systems", "description": "After reducing loads passively, students learn how efficient mechanical, electrical, lighting, and controls systems meet comfort needs with lower operational carbon.", "children": [{"id": "4aac602f-f243-4b5a-8c8b-38f77279f20c", "type": "subtopic", "title": "Energy loads and EUI", "children": [{"id": "6e6e2adb-4ca3-4ada-b36c-6ca4fd74c0a3", "type": "concept", "title": "Energy use intensity and end-use breakdowns"}, {"id": "0e1f29de-554e-40d9-a5f0-9c536a6ae60d", "type": "concept", "title": "Peak load, base load, and schedules"}, {"id": "968c96dd-24cd-422c-a270-03bee41ae578", "type": "concept", "title": "Benchmarking against code and high-performance targets"}], "description": "Students learn the vocabulary and metrics used to compare building energy performance."}, {"id": "7f839a8f-6df3-446b-8665-18f3432b4ff4", "type": "subtopic", "title": "HVAC and controls", "children": [{"id": "7a22f21c-9f79-485c-a569-bda871d5ccc8", "type": "concept", "title": "All-air, hydronic, heat pump, radiant, and DOAS systems"}, {"id": "4bcf9e4d-4789-45c8-ac4e-8ba7fb835e94", "type": "concept", "title": "Demand-controlled ventilation"}, {"id": "df0bae13-0b6b-44c1-a6cc-29241ac68df9", "type": "concept", "title": "Controls sequences and occupant interaction"}], "description": "This subtopic focuses on system selection, zoning, ventilation, heat recovery, and controls strategy."}, {"id": "6b168189-fdce-4970-9036-222457db3888", "type": "subtopic", "title": "Lighting and plug loads", "children": [{"id": "36ec51a0-3cea-49b3-bd35-311b329ad687", "type": "concept", "title": "LED efficiency and controls"}, {"id": "0583da92-a853-49a5-855f-e451e3a1cf4c", "type": "concept", "title": "Daylight dimming and occupancy sensors"}, {"id": "8477aaba-efd1-4056-b98b-51f1a89dfefa", "type": "concept", "title": "Equipment, appliances, and behavior"}], "description": "Students learn that non-HVAC loads often dominate high-performance buildings."}]}, {"id": "3799e4e1-bbbe-4bdd-a693-3d4656a4c220", "type": "topic", "title": "Renewable Energy and Electrification in Buildings", "description": "This topic connects building design to decarbonized energy systems. Students learn when on-site renewables, electrification, storage, and grid interaction are technically and economically appropriate.", "children": [{"id": "3b8a36f9-3695-4275-88bf-a18e65fd814a", "type": "subtopic", "title": "Building electrification", "children": [{"id": "def756db-1c39-4d49-937c-6d27d71bba29", "type": "concept", "title": "Heat pumps and heat pump water heating"}, {"id": "fbf279fd-e5b7-410d-b57e-292495191af7", "type": "concept", "title": "Cooking, backup systems, and resilience"}, {"id": "6d08600e-319a-4f44-911e-78d2db5035e0", "type": "concept", "title": "Grid emissions and time-of-use impacts"}], "description": "Students evaluate the shift from combustion-based systems to electric systems."}, {"id": "4abccb8c-adce-44ff-943e-b0a9188c76fa", "type": "subtopic", "title": "On-site renewable energy", "children": [{"id": "4dab3bc7-2fff-4236-8168-d2746b2eb5e6", "type": "concept", "title": "Photovoltaic orientation, tilt, shading, and capacity"}, {"id": "66ce98db-7a0c-4f22-bc75-61b45f96fe33", "type": "concept", "title": "Solar thermal and geothermal considerations"}, {"id": "f5351014-f979-4867-a452-a67ac9fce3cb", "type": "concept", "title": "Roof, facade, canopy, and site integration"}], "description": "This subtopic covers generation potential, placement, and design integration."}, {"id": "1c5c2c45-f77b-4770-875a-71875aba24ec", "type": "subtopic", "title": "Storage and grid interaction", "children": [{"id": "ce91c237-b35a-4094-818b-aced450626dd", "type": "concept", "title": "Battery storage and demand response"}, {"id": "bc931f84-21ab-4c4a-8f7d-82a58b5fdd4e", "type": "concept", "title": "Microgrids and critical loads"}, {"id": "ba66376b-2bbb-4596-955e-afc9a661c556", "type": "concept", "title": "Grid-interactive efficient buildings"}], "description": "Students learn how buildings can become flexible energy assets."}]}, {"id": "1f1938e0-5b15-4911-a3e3-adc78b93156c", "type": "topic", "title": "Water Conservation, Stormwater, and Site Ecology", "description": "Sustainable design treats water as a limited and living system. Students learn to reduce demand, reuse water where appropriate, manage stormwater, and support site ecology.", "children": [{"id": "77a7db10-62c0-4d6d-aa75-585bb24d398e", "type": "subtopic", "title": "Indoor and process water efficiency", "children": [{"id": "7d49d3d3-8029-4f9b-9239-f388ea1763c3", "type": "concept", "title": "Low-flow fixtures and appliance selection"}, {"id": "a3f2c770-70ba-4ea3-8f6f-f316fe512907", "type": "concept", "title": "Leak detection and metering"}, {"id": "43ede202-e9e3-4643-95b2-e62e8080f614", "type": "concept", "title": "Cooling tower and process water issues"}], "description": "Students learn to reduce potable water demand through fixtures, operations, and monitoring."}, {"id": "30e48579-fefe-494c-ace4-dc96f4d2a35e", "type": "subtopic", "title": "Rainwater, greywater, and reuse", "children": [{"id": "1dddbd78-6d50-4d3a-8a3b-61abeab98e1a", "type": "concept", "title": "Rainwater harvesting"}, {"id": "e7ed4947-2b72-4467-a0d7-a4ed346c7e5c", "type": "concept", "title": "Greywater reuse and treatment"}, {"id": "2203ca0c-5f7c-43e1-9605-4c9efd09dfc0", "type": "concept", "title": "Codes, health, maintenance, and user acceptance"}], "description": "This subtopic introduces strategies for matching water quality to water use."}, {"id": "7b0a63b2-87e9-4fc6-8280-db09d77bf6af", "type": "subtopic", "title": "Stormwater and landscape performance", "children": [{"id": "5ab25ad3-c8cb-42dc-bc1a-a7500ddc7ad8", "type": "concept", "title": "Green roofs, bioswales, and rain gardens"}, {"id": "43cec5c7-b6af-4363-b900-f5abfbba8eb6", "type": "concept", "title": "Permeable paving and detention"}, {"id": "20ac4543-61b7-4e1b-a6d5-d27401872041", "type": "concept", "title": "Native planting, biodiversity, and habitat"}], "description": "Students learn to design sites that slow, clean, infiltrate, and celebrate water."}]}, {"id": "baa2ac94-697b-42a7-a995-f7f336f9313b", "type": "topic", "title": "Materials, Life-Cycle Assessment, and Embodied Carbon", "description": "This course treats materials as climate decisions. Students learn life-cycle thinking, embodied carbon, environmental product declarations, and responsible specification.", "children": [{"id": "254ca8e1-597e-4817-a306-4e136eeba8c8", "type": "subtopic", "title": "Life-cycle assessment foundations", "children": [{"id": "9b99a1c3-7dec-4a51-a427-d055ad0e83f9", "type": "concept", "title": "Goal and scope definition"}, {"id": "8059c214-5d0a-4fcd-b152-ce658b83eb36", "type": "concept", "title": "Inventory, impact assessment, and interpretation"}, {"id": "b4b74af6-a66a-4ff6-8e6b-e51395d8ac9a", "type": "concept", "title": "Cradle-to-gate, cradle-to-grave, and whole-life carbon"}], "description": "Students learn the stages, boundaries, assumptions, and uncertainty behind LCA."}, {"id": "89629012-6ce5-4fef-a2be-5a71b6dc6056", "type": "subtopic", "title": "Embodied carbon in construction", "children": [{"id": "f29980ca-53a9-4c31-810d-8539aeff8149", "type": "concept", "title": "Concrete, steel, timber, masonry, and insulation"}, {"id": "ae7c22d9-b1c6-43f4-9970-4c149500a897", "type": "concept", "title": "Global warming potential and EPDs"}, {"id": "1fa971d6-20f9-4665-8fb1-5eeea6f7f72d", "type": "concept", "title": "Reduction strategies and procurement language"}], "description": "This subtopic focuses on the carbon implications of structure, envelope, finishes, and construction processes."}, {"id": "16d34039-d3e6-468f-b89a-ab887e81bf81", "type": "subtopic", "title": "Healthy and responsible materials", "children": [{"id": "3451e591-9da1-49dc-b395-ad9c39041b5a", "type": "concept", "title": "VOC emissions and chemical disclosure"}, {"id": "40f767bf-5187-45f2-aa6d-ea58431d305f", "type": "concept", "title": "FSC timber, recycled content, and regional sourcing"}, {"id": "54b6e387-1438-4659-b8b0-ab5637193c6b", "type": "concept", "title": "Durability, repairability, and replacement cycles"}], "description": "Students evaluate products for toxicity, transparency, sourcing, durability, and maintenance."}]}, {"id": "918461f6-c5cc-4c21-826b-88e2189808d9", "type": "topic", "title": "Circular Design, Deconstruction, and Waste", "description": "Circular design changes the question from 'How do we dispose of this?' to 'How do we keep value in use?' Students learn strategies for adaptability, reuse, repair, disassembly, and low-waste construction.", "children": [{"id": "f5457fc9-1782-4262-bb5a-832a94dbb7e5", "type": "subtopic", "title": "Design for adaptability", "children": [{"id": "5b599f90-adb5-4604-b180-81bab386d9e5", "type": "concept", "title": "Long-life loose-fit planning"}, {"id": "e9cfc6c3-b978-4ef1-bf36-1180ca8b92f3", "type": "concept", "title": "Structural grids and service zones"}, {"id": "81945274-adab-4549-8003-588d9fe9b2b5", "type": "concept", "title": "Flexible partitions and reversible decisions"}], "description": "Students plan buildings that can change use without unnecessary demolition."}, {"id": "69c47951-17f9-4cbe-9749-d955667e11b5", "type": "subtopic", "title": "Design for disassembly", "children": [{"id": "52bf8b27-426d-43f9-b892-ab62ff7d3c9a", "type": "concept", "title": "Mechanical fasteners and separable layers"}, {"id": "33bb231d-0acf-4e91-9743-e1e43e75e0b3", "type": "concept", "title": "Material passports and labeling"}, {"id": "e6369f9f-e5c2-4594-990b-ca20f752605d", "type": "concept", "title": "Selective demolition and salvage"}], "description": "This subtopic focuses on connections, documentation, and material recovery."}, {"id": "d780718b-3be4-4288-bfde-7d574dcd2345", "type": "subtopic", "title": "Construction and operational waste", "children": [{"id": "a65e8201-f665-4eaa-8cc4-f5df58fb7fc2", "type": "concept", "title": "Prefabrication and modularity"}, {"id": "1bece66b-012b-409c-9267-24bc4fb9b144", "type": "concept", "title": "Construction waste management plans"}, {"id": "57b77b3b-9f38-4811-a925-93fc3a71078f", "type": "concept", "title": "Composting, recycling, and user behavior"}], "description": "Students learn waste prevention as a design and delivery issue."}]}, {"id": "eacb06e8-0c68-405e-8f5b-2908dd775e98", "type": "topic", "title": "Indoor Environmental Quality, Health, and Well-Being", "description": "Sustainable buildings should support human health, dignity, comfort, and productivity. Students learn how air, light, sound, temperature, materials, and biophilic design affect occupants.", "children": [{"id": "0657bb30-7a17-46c4-babe-e80451ec1a66", "type": "subtopic", "title": "Indoor air quality", "children": [{"id": "7620da11-d240-414d-b07e-51d1c063c4f6", "type": "concept", "title": "Ventilation rates and filtration"}, {"id": "856e29ea-dbbf-4047-a302-ecccce52d4e3", "type": "concept", "title": "Low-emitting materials"}, {"id": "ebf5ce36-005d-4a98-b3e8-9de46448c7b2", "type": "concept", "title": "Moisture, mold, combustion, and pollutants"}], "description": "Students learn how ventilation, filtration, source control, and moisture management affect health."}, {"id": "65ba2207-b66c-454d-8a7b-90d7005c92d3", "type": "subtopic", "title": "Thermal, acoustic, and visual comfort", "children": [{"id": "2f79d23b-9953-4938-a372-1d13de8bc833", "type": "concept", "title": "Adaptive comfort and radiant asymmetry"}, {"id": "2c45e21b-68e7-4afe-92c2-a15b97ec269c", "type": "concept", "title": "Noise control and speech privacy"}, {"id": "64f5d286-35e7-4d35-a056-d56ca938dd82", "type": "concept", "title": "Views, circadian lighting, and glare"}], "description": "This subtopic connects comfort science to design choices."}, {"id": "da9bc0c2-5d3f-4cca-b060-0a81a77acfb5", "type": "subtopic", "title": "Biophilia and occupant well-being", "children": [{"id": "e6af4bc1-cde5-41c7-b272-851fa236ade4", "type": "concept", "title": "Views, daylight, plants, and natural materials"}, {"id": "1dba12f8-9f11-4fe2-a0cf-01a81d1daa51", "type": "concept", "title": "Refuge, prospect, pattern, and sensory richness"}, {"id": "83f8bc07-21e5-43ed-9795-033aa0b8c3c2", "type": "concept", "title": "Equity in access to healthy environments"}], "description": "Students explore evidence-informed ways to connect buildings with nature and human experience."}]}, {"id": "9d13614b-1c49-4ff6-ab8d-cb636015de52", "type": "topic", "title": "Certifications, Codes, Metrics, and Documentation", "description": "Certification systems are not a substitute for design judgment, but they can organize goals, documentation, and accountability. Students learn how to use rating systems without letting checklists drive shallow design.", "children": [{"id": "32019bd6-7815-4edc-a683-870deead5db5", "type": "subtopic", "title": "LEED and green building rating systems", "children": [{"id": "8dcd6dcc-b01b-4004-bb96-a53fb06f8ed0", "type": "concept", "title": "LEED credits and prerequisites"}, {"id": "49097da7-de11-46ad-80da-2a5e3048da95", "type": "concept", "title": "WELL, Living Building Challenge, Passive House, and BREEAM"}, {"id": "2ac49473-fb12-43eb-8571-5d1f2b5e08c9", "type": "concept", "title": "Choosing a framework for project goals"}], "description": "Students learn the structure, strengths, and limits of common certification frameworks."}, {"id": "f4ee9d10-c710-4ca8-a0c4-81e9af9e0917", "type": "subtopic", "title": "Codes, standards, and benchmarks", "children": [{"id": "ec50c6c5-85b8-4fd4-867d-63d817dacecf", "type": "concept", "title": "Energy codes and stretch codes"}, {"id": "c85994d5-5891-42ce-aee4-e8215f2e26f3", "type": "concept", "title": "ASHRAE standards"}, {"id": "c192f95a-b7c5-4c2c-927e-9a8acc9fc61b", "type": "concept", "title": "Benchmarking, targets, and compliance documentation"}], "description": "This subtopic connects design ambitions to regulatory and industry baselines."}, {"id": "4351d848-961d-490b-8079-c180644890df", "type": "subtopic", "title": "Metrics and evidence", "children": [{"id": "1aff43c8-2ba5-4efd-9f69-5cf984776ab8", "type": "concept", "title": "EUI, carbon, water, daylight, comfort, and waste metrics"}, {"id": "242960ca-9bc4-4bc9-9cb9-5d7616d169fb", "type": "concept", "title": "Design narratives and scorecards"}, {"id": "05660aef-131c-4316-b100-6859edad0fdf", "type": "concept", "title": "Avoiding unsupported sustainability claims"}], "description": "Students learn to document performance claims with measurable evidence."}]}, {"id": "a4f70cca-feb0-4660-9244-4d9d7f5314d0", "type": "topic", "title": "Net-Zero, Net-Positive, and Carbon-Neutral Design", "description": "Net-zero and carbon-neutral goals require disciplined definitions. Students learn to distinguish operational energy, operational carbon, embodied carbon, offsets, and whole-life carbon.", "children": [{"id": "54fd51ab-5968-4f52-a8d8-4648222b8d1b", "type": "subtopic", "title": "Net-zero energy", "children": [{"id": "8410defb-da8e-41b6-bce4-6498c60af836", "type": "concept", "title": "Load reduction before generation"}, {"id": "79d14265-99ca-4202-ab27-c7b6eabce1d0", "type": "concept", "title": "Source energy versus site energy"}, {"id": "3e70498b-2e0b-44d6-bbd8-1dc22244fd09", "type": "concept", "title": "Measurement periods and verification"}], "description": "Students learn how efficiency and renewables combine to meet annual energy targets."}, {"id": "cb2268a8-ed66-4f69-adf6-611ef73e0141", "type": "subtopic", "title": "Net-zero carbon and whole-life carbon", "children": [{"id": "8eaff545-358f-459f-acbc-668ef1b4834b", "type": "concept", "title": "Operational carbon and grid emissions"}, {"id": "fc923fb9-225e-4e3e-abf5-e0aa71468724", "type": "concept", "title": "Embodied carbon and refrigerants"}, {"id": "3797b72a-e058-4910-b858-ad3cb00b3fbc", "type": "concept", "title": "Whole-life carbon accounting"}], "description": "This subtopic extends beyond utility bills to life-cycle emissions."}, {"id": "ca8ea6bb-7dad-4880-a9cc-82d138652513", "type": "subtopic", "title": "Net-positive and regenerative goals", "children": [{"id": "bba6df26-6938-4818-babe-b83c1b43c61f", "type": "concept", "title": "Energy-positive and water-positive concepts"}, {"id": "e9a243b3-0faf-443d-85a5-7389beb7a80f", "type": "concept", "title": "Habitat and biodiversity gains"}, {"id": "50d29208-5ebb-4526-b633-3b1070533cb5", "type": "concept", "title": "Community resilience and social value"}], "description": "Students examine goals that go beyond reducing harm."}]}, {"id": "9e61d53b-139d-4f92-aa30-36aa79c594a4", "type": "topic", "title": "Resilience, Climate Adaptation, and Hazard Mitigation", "description": "Sustainable design must anticipate climate stress, disruption, and recovery. Students learn to design buildings and sites that remain useful, safe, and adaptable under changing conditions.", "children": [{"id": "24b94907-fb94-4791-a312-3ffc2a59ccd8", "type": "subtopic", "title": "Climate risk assessment", "children": [{"id": "91f30001-de8d-4df2-b559-f51a12a97b4a", "type": "concept", "title": "Heat, wildfire smoke, flooding, wind, drought, and storms"}, {"id": "0dc9eb9a-ea0d-4696-aeb4-b5e8cd53cf21", "type": "concept", "title": "Exposure, sensitivity, and adaptive capacity"}, {"id": "851e9e17-3f32-4dad-8eed-5fcccc3ddbd9", "type": "concept", "title": "Climate projections and scenario planning"}], "description": "Students identify hazards and vulnerabilities at site, building, and community scales."}, {"id": "4693aaf8-05b0-441b-9aed-8207ec8c371b", "type": "subtopic", "title": "Passive survivability and critical loads", "children": [{"id": "1eaeb18c-bd78-4e2a-b48d-9dcb0e24f650", "type": "concept", "title": "Thermal refuge during power loss"}, {"id": "c11c80fb-a201-4b9c-b891-65361c869ed0", "type": "concept", "title": "Backup power and critical circuits"}, {"id": "fd8d96c4-1f06-41b1-85f4-07a09b8cf141", "type": "concept", "title": "Water, sanitation, and communication needs"}], "description": "This subtopic addresses safety and function during outages or disrupted services."}, {"id": "f8c5097b-ee6e-4fa8-a0ad-6909bab007e3", "type": "subtopic", "title": "Adaptation strategies", "children": [{"id": "9cac8eaa-97c2-4e25-a9b4-b07cebdd4c68", "type": "concept", "title": "Floodable landscapes and elevated systems"}, {"id": "d9986de3-7aee-48ed-a724-dcaf79e6313b", "type": "concept", "title": "Fire-resistant detailing and defensible space"}, {"id": "386a8215-3785-47a1-88a1-4634921761ea", "type": "concept", "title": "Heat adaptation and shade networks"}], "description": "Students learn design moves that reduce future risk without undermining everyday performance."}]}, {"id": "cb27b6f8-547c-43bc-806d-50c583e503b2", "type": "topic", "title": "Equity, Environmental Justice, and Community Co-Benefits", "description": "Sustainable design is incomplete if it ignores unequal exposure to pollution, heat, cost burden, displacement, and poor-quality environments. Students learn to align performance with justice.", "children": [{"id": "8d52a8c2-1280-4324-8472-3b768784b757", "type": "subtopic", "title": "Environmental justice in the built environment", "children": [{"id": "e325f775-0f9a-4796-8c4e-c76310a7678f", "type": "concept", "title": "Heat islands, air pollution, and infrastructure inequity"}, {"id": "b99007eb-0cc8-4633-aa98-1294f4d0e440", "type": "concept", "title": "Displacement and green gentrification"}, {"id": "85bbbd8a-4c78-4935-9378-64fb4962dec3", "type": "concept", "title": "Community health and access to nature"}], "description": "Students learn how environmental burdens and amenities are unevenly distributed."}, {"id": "9d9bdbbd-1215-4602-b854-3aa2d0beaeaf", "type": "subtopic", "title": "Participatory design and local knowledge", "children": [{"id": "d62401b5-2cb6-4931-b39e-f24e59506725", "type": "concept", "title": "Stakeholder mapping and engagement plans"}, {"id": "a7d137bf-4872-438d-bf18-0b7648c9e730", "type": "concept", "title": "Listening sessions and co-design tools"}, {"id": "f7718b2d-0ff0-43b0-8780-9163b9577e66", "type": "concept", "title": "Transparency, consent, and accountability"}], "description": "This subtopic treats community expertise as essential design evidence."}, {"id": "a0d74c4a-9089-48af-add8-7288ce72af81", "type": "subtopic", "title": "Affordability and operational burden", "children": [{"id": "c06b244d-8694-4add-a408-8be6e26e1a71", "type": "concept", "title": "Energy burden and utility costs"}, {"id": "9a1dd0b8-e0b0-452b-97b2-79cff022ba75", "type": "concept", "title": "Maintenance capacity and user training"}, {"id": "a12399a3-47f8-4105-a488-0c8e697ae3c1", "type": "concept", "title": "Durability, repair, and low-cost operation"}], "description": "Students evaluate sustainability through lifecycle cost and everyday usability."}]}, {"id": "96c24ab7-b4d8-4381-90b5-9ff542504fb2", "type": "topic", "title": "Building Performance Modeling, Simulation, and Uncertainty", "description": "Simulation helps designers compare options, but it depends on assumptions. Students learn to use modeling as decision support rather than as a magic answer machine.", "children": [{"id": "63d12cd9-9958-41b3-bbc7-917b47fe9780", "type": "subtopic", "title": "Energy and daylight modeling", "children": [{"id": "21ca7779-c57a-45ab-829c-4fee7efd1eb8", "type": "concept", "title": "Baseline models and parametric comparisons"}, {"id": "65810138-2aad-42ee-b87a-dd2b9dc46758", "type": "concept", "title": "Daylight autonomy, glare, and shading studies"}, {"id": "277d468e-a0a0-4f61-b468-660674df4994", "type": "concept", "title": "Energy use intensity and end-use analysis"}], "description": "Students learn what modeling can reveal at concept, schematic, and detailed design stages."}, {"id": "a1eb6583-d21c-452e-a318-61346b806d37", "type": "subtopic", "title": "Carbon and water analysis tools", "children": [{"id": "4e8294c5-5200-4d87-802d-83f6111dff77", "type": "concept", "title": "Embodied carbon tools and LCA databases"}, {"id": "1a799555-93bd-427c-9af1-dfc54981088b", "type": "concept", "title": "Water balance and stormwater models"}, {"id": "75442ef5-c5b4-4f33-82ab-da06ab2310e1", "type": "concept", "title": "Scenario comparison and sensitivity analysis"}], "description": "This subtopic introduces integrated metrics beyond energy."}, {"id": "852cc366-5d41-442c-8d9c-84141408c532", "type": "subtopic", "title": "Uncertainty and communication", "children": [{"id": "f649ea51-000f-4c5c-b987-a4605c57ade0", "type": "concept", "title": "Input assumptions and calibration"}, {"id": "ce782325-6c02-43fa-a0aa-ac26970eb52c", "type": "concept", "title": "Sensitivity and uncertainty ranges"}, {"id": "9c26f88f-d070-47a2-90ab-95c158871974", "type": "concept", "title": "Clear graphics for design teams and clients"}], "description": "Students learn to explain assumptions, limits, and confidence honestly."}]}, {"id": "059e2f8d-6251-41fb-a02b-782703c81b26", "type": "topic", "title": "Economics, Delivery, Operations, Commissioning, and Post-Occupancy Evaluation", "description": "Performance is achieved through delivery and operations, not just design intent. Students learn lifecycle cost, commissioning, operations, measurement, and feedback.", "children": [{"id": "622b5009-ed30-4b65-9987-36bf3bac6924", "type": "subtopic", "title": "Lifecycle cost and value", "children": [{"id": "e7cf414d-13f7-4c4a-948b-6ed93f0b2034", "type": "concept", "title": "Capital cost and operating cost"}, {"id": "db1792b7-56ca-4a34-8683-cbdaae9488e8", "type": "concept", "title": "Payback, NPV, and nonfinancial value"}, {"id": "2cc495c9-b44b-43e7-8318-7fb199ad98a1", "type": "concept", "title": "Incentives, procurement, and budget tradeoffs"}], "description": "Students compare first cost with long-term performance, maintenance, risk, and social value."}, {"id": "b5f1c0b0-6b64-4bf5-95ff-bc94cae3383e", "type": "subtopic", "title": "Commissioning and operations", "children": [{"id": "a43f0d57-66c3-4195-80a0-43cf3466de29", "type": "concept", "title": "Owner project requirements"}, {"id": "a16dd2d6-7401-41a3-9e73-77584ec020a0", "type": "concept", "title": "Functional testing and systems tuning"}, {"id": "e5c2fb00-422c-4aee-a52a-d314994d5626", "type": "concept", "title": "Facilities training and controls handover"}], "description": "This subtopic explains how design intent becomes working building performance."}, {"id": "51bc09f6-5849-4825-9e34-c12774618525", "type": "subtopic", "title": "Post-occupancy evaluation", "children": [{"id": "f2835e0e-c837-4bea-8cee-5d8c61ef9a3e", "type": "concept", "title": "Energy, water, and comfort measurement"}, {"id": "b6d36d7f-ac0a-4ca5-ac90-3b5918821b67", "type": "concept", "title": "Occupant surveys and interviews"}, {"id": "09b82c4d-5cb3-4e8d-b33b-53d784a49a14", "type": "concept", "title": "Lessons learned for future projects"}], "description": "Students learn to close the feedback loop between design claims and lived performance."}]}, {"id": "2cce7229-6ac7-4669-bdd0-2e3e0303e272", "type": "topic", "title": "Integrated Sustainable Design Studio / Capstone", "description": "The capstone requires students to integrate climate, carbon, water, materials, health, equity, and beauty into a coherent design proposal with evidence.", "children": [{"id": "8c7f530f-2848-4f8b-9a61-e9172f65c446", "type": "subtopic", "title": "Project brief and performance goals", "children": [{"id": "a280685a-1532-49e0-a9ee-320a88e84574", "type": "concept", "title": "Site and climate brief"}, {"id": "c5cc4e72-b6e1-4cde-aeec-4a8b8d95d02b", "type": "concept", "title": "Performance scorecard"}, {"id": "31793284-3483-4860-b5ae-c3d79d5fd117", "type": "concept", "title": "Stakeholder and equity goals"}], "description": "Students define a project problem and translate values into measurable design goals."}, {"id": "3942fe6f-33bb-4a00-b4c2-ed6eb67e59f8", "type": "subtopic", "title": "Iterative design and analysis", "children": [{"id": "1017d435-edbd-4122-bcf6-d147c7cc8200", "type": "concept", "title": "Option testing and tradeoff diagrams"}, {"id": "13e6a078-2394-43dc-8c1d-60d8b85e9b02", "type": "concept", "title": "Simulation-informed design moves"}, {"id": "3184153f-09b0-4395-b1e1-d8f000ccb7ef", "type": "concept", "title": "Integrated architectural, structural, and systems thinking"}], "description": "This subtopic turns analysis into design decisions and revisions."}, {"id": "19a18432-161e-426e-a741-bec32bbdd507", "type": "subtopic", "title": "Final sustainability dossier", "children": [{"id": "fbbb7841-0431-4ae1-9690-7691df0f2e1b", "type": "concept", "title": "Drawings, diagrams, and narratives"}, {"id": "fa0a7b94-ccb9-4632-9975-c142feff4caa", "type": "concept", "title": "Carbon, energy, water, and material evidence"}, {"id": "219423b9-fd2f-4646-9af1-f33b0a818554", "type": "concept", "title": "Reflection on tradeoffs and next steps"}], "description": "Students present a clear, evidence-based design package for review."}]}], "dbBacked": true}$susdjson$::jsonb,
